INSERT INTO book (id, title, summary, language, created_at) VALUES
('b0000001-0000-0000-0000-000000000001', 'Harry Potter and the Philosopher''s Stone', 'A young wizard discovers his magical heritage and battles dark forces at Hogwarts School.', 'English', '1997-06-26T00:00:00Z'),
('b0000001-0000-0000-0000-000000000002', 'The Lord of the Rings: The Fellowship of the Ring', 'A hobbit embarks on an epic quest to destroy a powerful ring and save Middle-earth.', 'English', '1954-07-29T00:00:00Z'),
('b0000001-0000-0000-0000-000000000003', '1984', 'A dystopian novel set in a totalitarian society ruled by Big Brother.', 'English', '1949-06-08T00:00:00Z'),
('b0000001-0000-0000-0000-000000000004', 'Pride and Prejudice', 'The story of Elizabeth Bennet as she navigates love and social expectations.', 'English', '1813-01-28T00:00:00Z'),
('b0000001-0000-0000-0000-000000000005', 'Les Misérables', 'An epic story of justice, love, and redemption in post-revolutionary France.', 'French', '1862-01-01T00:00:00Z'),
('b0000001-0000-0000-0000-000000000006', 'Crime and Punishment', 'A young intellectual commits murder and struggles with guilt and morality.', 'Russian', '1866-01-01T00:00:00Z'),
('b0000001-0000-0000-0000-000000000007', 'The Shining', 'A family becomes trapped in a haunted hotel during winter, descending into madness.', 'English', '1977-01-28T00:00:00Z'),
('b0000001-0000-0000-0000-000000000008', 'Kafka on the Shore', 'A surreal journey intertwining the fates of a boy and an old man.', 'Japanese', '2002-09-12T00:00:00Z'),
('b0000001-0000-0000-0000-000000000009', 'Murder on the Orient Express', 'Detective Hercule Poirot investigates a murder aboard a luxury train.', 'English', '1934-01-01T00:00:00Z'),
('b0000001-0000-0000-0000-000000000010', 'Foundation', 'A mathematician predicts the fall of the Galactic Empire and plans to save civilization.', 'English', '1951-01-01T00:00:00Z'),
('b0000001-0000-0000-0000-000000000011', 'Soumission', 'A political satire set in a near-future France where an Islamic party comes to power.', 'French', '2015-01-07T00:00:00Z'),
('b0000001-0000-0000-0000-000000000012', 'Stupeur et Tremblements', 'A young Belgian woman navigates the absurdities of corporate Japan.', 'French', '1999-08-19T00:00:00Z'),
('b0000001-0000-0000-0000-000000000013', 'Comme un roman', 'A plea for the joy of reading and the right to not read.', 'French', '1992-01-01T00:00:00Z'),
('b0000001-0000-0000-0000-000000000014', 'American Gods', 'A storm is coming, and old gods and new gods are preparing for battle.', 'English', '2001-06-19T00:00:00Z'),
('b0000001-0000-0000-0000-000000000015', 'Cosmos', 'A journey through the universe exploring science, astronomy, and humanity''s place in it.', 'English', '1980-01-01T00:00:00Z');
